with Recursive_Badge_Value as 
(
    select 
        u.Id as UserId
      , u.DisplayName
      , b.Class
      , row_number() over (partition by u.Id order by b.Date desc) as rn
      , concat(b.Name, ' [Added on: ', to_char(b.Date, 'YYYY-MM-DD'), ']') BadgeDetail
      , b.Date
    from Users u
    left join Badges b on b.UserId = u.Id
    where b.Class is not null
), 
